package com.bank.merge.service;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Minimum total cost to merge all batches by always joining the two smallest.
public class BatchMergeService {
    private static final Logger log = Logger.getLogger(BatchMergeService.class.getName());

    public int minMergeCost(int[] sizes) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int size : sizes) minHeap.offer(size);     // O(n) load
        int total = 0;
        while (minHeap.size() > 1) {
            int first = minHeap.poll();                  // two smallest
            int second = minHeap.poll();
            int cost = first + second;                   // cost of this merge
            total += cost;                               // accumulate
            minHeap.offer(cost);                         // combined batch re-enters
            final int c = cost, t = total;
            log.fine(() -> "Merged " + first + "+" + second + "=" + c + " runningTotal=" + t);
        }
        final int result = total;
        log.info(() -> "Minimum merge cost = " + result);
        return total;
    }
}
